import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

async function CardStatsSection() {
  const data = await getDashboardData()

  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartSection() {
  const data = await getDashboardData()

  return <RevenueChart revenue={data.revenue} />
}

async function LatestInvoicesSection() {
  const data = await getDashboardData()

  return <LatestInvoices invoices={data.invoices} />
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense
        fallback={
          <div className="grid grid-cols-2 gap-4">
            <div className="card">
              <h2>Total Revenue</h2>
              <p>Loading...</p>
            </div>
            <div className="card">
              <h2>Total Invoices</h2>
              <p>Loading...</p>
            </div>
          </div>
        }
      >
        <CardStatsSection />
      </Suspense>
      <Suspense
        fallback={
          <div className="chart">
            <h2>Revenue</h2>
            <p>Loading...</p>
          </div>
        }
      >
        <RevenueChartSection />
      </Suspense>
      <Suspense
        fallback={
          <div className="invoices">
            <h2>Latest Invoices</h2>
            <p>Loading...</p>
          </div>
        }
      >
        <LatestInvoicesSection />
      </Suspense>
    </main>
  )
}

